// limiter.go
package tokenbucket

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock supplies the current time. It is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
//
// Tokens are replenished continuously at rate tokens per second, up to capacity.
// A call consumes tokens atomically; fractional tokens are retained internally.
type Limiter struct {
	mu sync.Mutex

	clock    Clock
	rate     float64
	capacity float64

	tokens float64
	last   time.Time
}

// Config configures a Limiter.
type Config struct {
	// Rate is the number of tokens added per second. Must be > 0 and finite.
	Rate float64
	// Capacity is the maximum bucket size. Must be > 0 and finite.
	Capacity float64
	// Clock is optional; time.Now is used when nil.
	Clock Clock
	// InitialTokens is optional; defaults to Capacity. Must be in [0, Capacity].
	InitialTokens *float64
}

var (
	ErrInvalidRate          = errors.New("tokenbucket: rate must be > 0 and finite")
	ErrInvalidCapacity      = errors.New("tokenbucket: capacity must be > 0 and finite")
	ErrInvalidInitialTokens = errors.New("tokenbucket: initial tokens must be finite and within [0, capacity]")
)

// New validates cfg and returns a ready-to-use Limiter.
func New(cfg Config) (*Limiter, error) {
	if cfg.Rate <= 0 || !isFinite(cfg.Rate) {
		return nil, ErrInvalidRate
	}
	if cfg.Capacity <= 0 || !isFinite(cfg.Capacity) {
		return nil, ErrInvalidCapacity
	}

	initial := cfg.Capacity
	if cfg.InitialTokens != nil {
		initial = *cfg.InitialTokens
		if !isFinite(initial) || initial < 0 || initial > cfg.Capacity {
			return nil, ErrInvalidInitialTokens
		}
	}

	c := cfg.Clock
	if c == nil {
		c = systemClock{}
	}

	return &Limiter{
		clock:    c,
		rate:     cfg.Rate,
		capacity: cfg.Capacity,
		tokens:   initial,
		last:     c.Now(),
	}, nil
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n tokens are available and consumes them if so.
//
// n must be positive, finite, and <= capacity. Invalid or oversized requests
// are rejected without consuming tokens. Time never moves backwards: a clock
// regression is ignored until the clock catches up to the last observed time.
func (l *Limiter) AllowN(n float64) bool {
	if !isFinite(n) || n <= 0 || n > l.capacity {
		return false
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		if elapsed > 0 {
			l.tokens = minFloat(l.capacity, l.tokens+l.rate*elapsed)
		}
		l.last = now
	}

	if l.tokens < n {
		return false
	}
	l.tokens -= n
	return true
}

// Tokens returns the currently available tokens after applying elapsed time.
// It is primarily useful for diagnostics and tests.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		if elapsed > 0 {
			l.tokens = minFloat(l.capacity, l.tokens+l.rate*elapsed)
		}
		l.last = now
	}
	return l.tokens
}

func minFloat(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}

func isFinite(v float64) bool {
	return !isNaN(v) && !isInf(v)
}

// Avoid importing math for two tiny predicates while keeping the package compact.
func isNaN(v float64) bool { return v != v }
func isInf(v float64) bool { return v > maxFloat || v < -maxFloat }

const maxFloat = 1.7976931348623157e308

// String implements a compact diagnostic representation.
func (l *Limiter) String() string {
	return fmt.Sprintf("tokenbucket.Limiter(rate=%g, capacity=%g, tokens=%g)", l.rate, l.capacity, l.Tokens())
}
