// limiter.go
package tokenbucket

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock supplies the current time. It is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type systemClock struct{}

func (systemClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// It refills continuously at rate tokens per second up to capacity tokens.
type Limiter struct {
	mu sync.Mutex

	capacity float64
	rate     float64 // tokens per second
	clock    Clock

	tokens float64
	last   time.Time
}

// New creates a Limiter with the given capacity, refill rate, and clock.
// If clock is nil, the system clock is used. The bucket starts full.
func New(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || isInvalidFloat(capacity) {
		return nil, errors.New("tokenbucket: capacity must be a finite positive number")
	}
	if rate <= 0 || isInvalidFloat(rate) {
		return nil, errors.New("tokenbucket: rate must be a finite positive number")
	}
	if clock == nil {
		clock = systemClock{}
	}

	now := clock.Now()
	return &Limiter{
		capacity: capacity,
		rate:     rate,
		clock:    clock,
		tokens:   capacity,
		last:     now,
	}, nil
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n tokens are available and consumes them if so.
// n must be positive and no greater than capacity. Requests larger than
// capacity can never succeed and are rejected without consuming tokens.
func (l *Limiter) AllowN(n int64) bool {
	if n <= 0 || float64(n) > l.capacity {
		return false
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	l.refill(now)

	need := float64(n)
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Tokens returns the currently available token count after applying refill.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

// refill applies elapsed-time refill. Caller must hold l.mu.
func (l *Limiter) refill(now time.Time) {
	if now.Before(l.last) {
		// Ignore non-monotonic clock movement; do not rewind or mint tokens.
		l.last = now
		return
	}

	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.last = now

	if isInvalidFloat(elapsed) {
		return
	}
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity || isInvalidFloat(l.tokens) {
		l.tokens = l.capacity
	}
}

func isInvalidFloat(v float64) bool {
	return v != v || v > 1.7976931348623157e308 || v < -1.7976931348623157e308
}

// String implements fmt.Stringer for diagnostics.
func (l *Limiter) String() string {
	l.mu.Lock()
	defer l.mu.Unlock()
	return fmt.Sprintf("Limiter(capacity=%g, rate=%g, tokens=%g)", l.capacity, l.rate, l.tokens)
}
