// limiter.go
package tokenbucket

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock supplies the current time. It is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// It refills continuously at rate tokens per second up to capacity tokens.
type Limiter struct {
	mu sync.Mutex

	clock    Clock
	rate     float64
	capacity float64

	tokens float64
	last   time.Time
}

// New creates a Limiter with the given refill rate (tokens/second), capacity,
// and optional clock. If clock is nil, the system clock is used.
// The bucket starts full.
func New(rate, capacity float64, clock Clock) (*Limiter, error) {
	if rate <= 0 || !(rate > 0) {
		return nil, errors.New("tokenbucket: rate must be > 0 and finite")
	}
	if capacity <= 0 || !(capacity > 0) {
		return nil, errors.New("tokenbucket: capacity must be > 0 and finite")
	}
	if isInf(rate) || isInf(capacity) {
		return nil, errors.New("tokenbucket: rate and capacity must be finite")
	}
	if clock == nil {
		clock = realClock{}
	}

	now := clock.Now()
	return &Limiter{
		clock:    clock,
		rate:     rate,
		capacity: capacity,
		tokens:   capacity,
		last:     now,
	}, nil
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n tokens are available and consumes them if so.
// n must be positive and no greater than capacity. Fractional n is allowed.
func (l *Limiter) AllowN(n float64) bool {
	if n <= 0 || !(n > 0) || isInf(n) {
		return false
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	l.refill(now)
	if n > l.capacity || l.tokens < n {
		return false
	}
	l.tokens -= n
	return true
}

// Tokens returns the currently available token count after refilling.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

func (l *Limiter) refill(now time.Time) {
	if now.Before(l.last) {
		// Ignore non-monotonic clock movement; keep last to avoid negative refill.
		return
	}
	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.last = now
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
}

func isInf(v float64) bool {
