func TestConcurrentAllowN(t *testing.T) {
	fc := newFakeClock(time.Unix(0, 0).UTC())
	const capacity = 100
	l, err := New(0, capacity, fc)
	if err == nil {
		t.Fatal("expected zero-rate validation error")
	}
	l, err = New(1, capacity, fc)
	if err != nil {
		t.Fatal(err)
	}

	const goroutines = 200
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0

	for i := 0; i < goroutines; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.AllowN(1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()

	if allowed != capacity {
		t.Fatalf("allowed=%d, want %d", allowed, capacity)
	}
	if got := l.Tokens(); !almostEqual(got, 0) {
		t.Fatalf("tokens=%v, want 0", got)
	}
}

func almostEqual(a, b float64) bool {
	return math.Abs(a-b) <= 1e-9
}
